async (page) => {
  const response = await page.request.get('http://the-agent-company.com:8092/remote.php/dav/files/theagentcompany/Documents/command.txt', {
    headers: {
      'Authorization': 'Basic ' + Buffer.from('theagentcompany:theagentcompany').toString('base64')
    }
  });
  const text = await response.text();
  const fs = require('fs');
  fs.writeFileSync('/tmp/command.txt', text);
  return { status: response.status(), text: text };
}
